constructor(core: PathlandCore) {
    this.core = core
    this.handle = core.create()
}

/** The opaque native handle (for direct ring access). */
fun handle(): Pointer = handle

override fun beginFrame() = core.beginFrame(handle)
override fun endFrame() = core.endFrame(handle)

override fun createNode(id: Int, component: Int) {
    push(Categories.TREE, Commands.Tree.CREATE_NODE, 0, id, component, 0)
}

override fun deleteNode(id: Int) {
    push(Categories.TREE, Commands.Tree.DELETE_NODE, 0, id, 0, 0)
}

override fun insertChild(parent: Int, child: Int, index: Int) {
    push(Categories.TREE, Commands.Tree.INSERT_CHILD, 0, parent, child, index)
}

override fun removeChild(parent: Int, child: Int) {
    push(Categories.TREE, Commands.Tree.REMOVE_CHILD, 0, parent, child, 0)
}

override fun moveChild(parent: Int, child: Int, newIndex: Int) {
    push(Categories.TREE, Commands.Tree.MOVE_CHILD, 0, parent, child, newIndex)
}

override fun setText(nodeId: Int, text: String) {
    val ref = core.arenaAlloc(handle, text.toByteArray(StandardCharsets.UTF_8))
    push(Categories.PARAMETER, Commands.Parameter.SET_TEXT, 0, nodeId, ref, 0)
}

override fun setAttributedText(nodeId: Int, value: dev.pathland.core.text.AttributedString) {
    val ref = core.arenaAlloc(handle, value.encode())
    push(Categories.PARAMETER, Commands.Parameter.SET_ATTRIBUTED_TEXT, 0, nodeId, ref, 0)
}

override fun setProperty(nodeId: Int, property: Int, valueType: Int, value: Any) {
    val b = (valueType shl 16) or (property and 0xFFFF)
    when (valueType) {
        ValueTypes.STRING -> {
            val ref = core.arenaAlloc(handle, (value as String).toByteArray(StandardCharsets.UTF_8))
            push(Categories.PARAMETER, Commands.Parameter.SET_PROPERTY, 0, nodeId, b, ref)
        }
        ValueTypes.DESIGN_TOKEN -> {
            val ref = core.arenaAlloc(handle,
                ((value as TokenPath).tokenPath() ?: "").toByteArray(StandardCharsets.UTF_8))
            push(Categories.PARAMETER, Commands.Parameter.SET_PROPERTY, 0, nodeId, b, ref)
        }
        ValueTypes.LIST -> {
            val ref = core.arenaAlloc(handle, encodeList(value as FloatArray))
            push(Categories.PARAMETER, Commands.Parameter.SET_PROPERTY, 0, nodeId, b, ref)
        }
        else -> push(Categories.PARAMETER, Commands.Parameter.SET_PROPERTY, 0, nodeId, b,
            ValueEncoder.encodeBits(valueType, value))
    }
}

private fun encodeList(elements: FloatArray): ByteArray {
    val out = ByteArray(4 + 4 * elements.size)
    var value = elements.size
    out[0] = (value and 0xFF).toByte()
    out[1] = ((value ushr 8) and 0xFF).toByte()
    out[2] = ((value ushr 16) and 0xFF).toByte()
    out[3] = ((value ushr 24) and 0xFF).toByte()
    for (i in elements.indices) {
        val bits = elements[i].toRawBits()
        val o = 4 + 4 * i
        out[o] = (bits and 0xFF).toByte()
        out[o + 1] = ((bits ushr 8) and 0xFF).toByte()
        out[o + 2] = ((bits ushr 16) and 0xFF).toByte()
        out[o + 3] = ((bits ushr 24) and 0xFF).toByte()
    }
    return out
}

override fun setDate(nodeId: Int, days: Int, millisOfDay: Int) {
    push(Categories.PARAMETER, Commands.Parameter.SET_DATE, 0, nodeId, days, millisOfDay)
}

override fun setDesignToken(path: String, valueType: Int, value: Any) {
    val pathRef = core.arenaAlloc(handle, path.toByteArray(StandardCharsets.UTF_8))
    val c = if (valueType == ValueTypes.STRING) {
        core.arenaAlloc(handle, (value as String).toByteArray(StandardCharsets.UTF_8))
    } else {
        ValueEncoder.encodeBits(valueType, value)
    }
    push(Categories.PARAMETER, Commands.Parameter.SET_DESIGN_TOKEN, 0, pathRef, valueType, c)
}

private fun push(category: Int, command: Int, flags: Int, a: Int, b: Int, c: Int) {
    core.push(handle, Opcode(category, command, flags, a, b, c).toBytes())
}

override fun requiresBindingId(): Boolean = true

override fun close() {

/// signal-backed, so a route can drive them from a computed. The next
/// [`Engine::emit`] writes the initial values; a subsequent
/// [`Engine::set_signal`] writes only the changed field.
pub fn bind_window_metadata(&mut self, metadata: WindowMetadata) {
    self.window = metadata;
}

/// Bind one window-metadata field to a signal (the flat/C-ABI form of
/// [`Engine::bind_window_metadata`]).
pub fn bind_window_field(&mut self, field: u16, signal: SignalId) {
    self.window.set_signal(field, signal);
}

/// Emit changed window-metadata fields. Unchanged fields write nothing; a
/// field that became unset writes an empty string (clear).
fn emit_window_metadata(
    &mut self,
    guest: &mut Guest<'_>,
) -> Result<usize, pathland_core::RingError> {
    let mut out = 0usize;
    for field in window_field::ALL {
        let value = self.window.signal(field).and_then(|id| {
            let value = self.store.get(id);
            value.to_text().map(ToOwned::to_owned)
        });
        let previous = self.window_emitted.get(field).map(ToOwned::to_owned);
        if value == previous {
            continue;
        }
        let text = value.as_deref().unwrap_or("");
        let offset = guest
            .alloc_str(text)
            .map_err(|_| pathland_core::RingError::Full)?;
        guest.push_opcode(Opcode::new(
            category::META,
            meta::SET_WINDOW_METADATA,
            0,
            field as u32,
            offset,
            0,
        ))?;
        self.window_emitted.set(field, text);
        out += 1;
    }
    Ok(out)
}

/// Emit a global design-token override (`PARAMETER::SET_DESIGN_TOKEN`).
/// Overrides are renderer-global and apply everywhere the renderer resolves
/// tokens; a `dark.`-prefixed path overrides the dark variant
/// (spec/TOKENS.md). Returns the arena offset of the token path.
    self.reset_theme(guest)?;
    self.apply_adaptive_theme(adaptive, guest)
}

/// Emit one `SET_DESIGN_TOKEN` override, arena-allocating STRING values.
fn emit_token_override(
    &mut self,
    path: &str,
    value: &pathland_core::tokens::TokenValue,
    guest: &mut Guest<'_>,
) -> Result<(), pathland_core::RingError> {
    use pathland_core::tokens::TokenValue;
    match value {
        TokenValue::Str(s) => {
            let ref_ = guest
                .alloc_str(s)
                .map_err(|_| pathland_core::RingError::Full)?;
            guest.set_design_token(path, value.value_type(), ref_)?;
        }
        _ => {
            if let Some(bits) = value.to_bits() {
                guest.set_design_token(path, value.value_type(), bits)?;
            }
        }
    }
    Ok(())

    fun destroy(handle: Pointer) {
        nativeCore.pathland_core_destroy(handle)
    }

    // --- guest → host ring ---

    /** Push one 16-byte opcode into the shared ring. Returns false when full. */
    fun push(handle: Pointer, opcode: ByteArray): Boolean {
        opcodeBuf.write(0, opcode, 0, Opcode.SIZE)
        return nativeCore.pathland_ring_buffer_push(handle, opcodeBuf)
    }

    /** Allocate bytes into the bump arena, returning the absolute offset. */
    fun arenaAlloc(handle: Pointer, bytes: ByteArray): Int {
        val buf = Memory(maxOf(1, bytes.size).toLong())
        if (bytes.isNotEmpty()) {
            buf.write(0, bytes, 0, bytes.size)
        }
        return nativeCore.pathland_core_arena_alloc(handle, buf, bytes.size)
    }

    fun beginFrame(handle: Pointer) {
        nativeCore.pathland_core_begin_frame(handle)
    }

    fun endFrame(handle: Pointer) {
        nativeCore.pathland_core_end_frame(handle)
    }

    fun frameCount(handle: Pointer): Int = nativeCore.pathland_core_frame_count(handle)

    /** Pointer to the shared linear memory (header | ring | arena). */
    fun ringPtr(handle: Pointer): Pointer = nativeCore.pathland_core_ring_ptr(handle)

    /** Byte length of the shared linear memory. */
    fun ringLen(handle: Pointer): Long = nativeCore.pathland_core_ring_len(handle)

    /** Borrow the underlying shared ring for a same-process consumer. */
    fun ringMut(handle: Pointer): Pointer = nativeCore.pathland_core_ring_mut(handle)

    // --- events (host → guest) ---

    /** Drain pending EVENT opcodes into [out]; returns the number written. */
    fun drainEvents(handle: Pointer, out: Pointer, max: Int): Int =
        nativeCore.pathland_core_drain_events(handle, out, max)

    /** Push one 16-byte EVENT opcode into the host → guest event ring. */
    fun sendEvent(handle: Pointer, opcode: ByteArray): Boolean {
        opcodeBuf.write(0, opcode, 0, Opcode.SIZE)
        return nativeCore.pathland_core_send_event(handle, opcodeBuf)
    }

