            .unwrap();
        guest
            .set_property(1, property_id::PADDING_TOP, value_type::F32, 2.0f32.to_bits())
            .unwrap();
        guest.create_node(2, component_type::TEXT).unwrap();
        guest.insert_child(1, 2, APPEND).unwrap();
        guest.set_text(2, "hi").unwrap();
        guest.end_frame();
