package dev.pathland.server;


import dev.pathland.view.core.ThemeData;
import dev.pathland.view.core.View;

/**
 * The application's root-view factory — the single app-specific piece the server
 * runtime needs. A host (Spring Boot / Quarkus starter) provides one as a bean; the
 * runtime mounts a fresh root per session (views hold per-session {@code State}).
 *
 * <pre>{@code
 * @Bean PathlandApp pathlandApp() { return () -> new MyHomeView(); }
 * }</pre>
 */
@FunctionalInterface
public interface PathlandApp {

    /** A fresh root view for a new session. */
    View newRoot();

    /** The optional global theme (design-token overrides); {@code null} for none. */
    default ThemeData theme() {
        return null;
    }

    /**
     * Optional per-route document metadata for the SSR head (canonical URL,
     * Open Graph/Twitter cards, JSON-LD). Called before the first render with
     * the active route, so an app can make metadata route-specific.
     *
     * <p>Returned non-null fields override the host defaults built from the
     * request URL and {@code pathland.seo.*} config. The default returns no
     * overrides.
     */
    default PageMetadata pageMetadata(PageMetadataRequest request) {
        return PageMetadata.empty();
    }
}
    /** A connection that records the decoded SET_TEXT values it received. */
    private static final class RecordingConnection implements PathlandConnection {
        private final List<byte[]> recorded = new CopyOnWriteArrayList<>();

        @Override
        public void send(byte[] bytes) {
            recorded.add(bytes);
        }

        @Override
        public boolean isOpen() {
            return true;
        }

        List<String> setTextValues() {
            List<String> values = new ArrayList<>();
            for (byte[] bytes : recorded) {
                try {
                    ProtocolFrame frame = FrameCodec.decodeFrame(bytes);
                    for (Opcode op : frame.opcodes()) {
                        if (op.category() == 0x02 && op.command() == 0x03) { // PARAMETER::SET_TEXT
                            values.add(frame.stringAt(op.b()));
                        }
                    }
                } catch (RuntimeException ignored) {
                    // a partial/undecodable batch — keep scanning
                }
            }
            return values;
        }

        boolean hasText(String text) {
            return setTextValues().contains(text);
        }
    }
}package dev.pathland.server;

/**
 * The transport seam (spec DSL.md §4.5): the server runtime sends delta frames through
 * this, so the session logic is framework-agnostic. Each starter adapts its WebSocket
 * type (Spring {@code WebSocketSession}, Quarkus {@code WebSocketConnection}) to it.
 */
public interface PathlandConnection {

    /** Send a self-contained delta/snapshot frame to this connection's client. */
    void send(byte[] bytes);

    /** Whether the connection can currently accept a send. */
    boolean isOpen();
}

