QQuickLayoutAttached *layoutAttached(QQuickItem *item) {
    if (!item) {
        return nullptr;
    }
    return qobject_cast<QQuickLayoutAttached *>(
        qmlAttachedPropertiesObject<QQuickLayout>(item, /*create=*/true));
