import { chromium } from '@playwright/test';
const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
await page.goto('http://localhost:8090/', { waitUntil: 'domcontentloaded', timeout: 15000 });
await page.waitForSelector('[data-pathland-lazy]', { timeout: 20000 });
const snap = () => page.evaluate(() => {
  const el = document.querySelector('[data-pathland-lazy]');
  let sc = el.parentElement;
  while (sc && sc !== document.body) {
    const s = getComputedStyle(sc);
    if (/auto|scroll|overlay/.test(s.overflowY)) break;
    sc = sc.parentElement;
  }
  const kids = Array.from(el.children);
  const visible = kids.filter((k) => {
    const r = k.getBoundingClientRect();
    const sr = sc.getBoundingClientRect();
    return r.bottom > sr.top && r.top < sr.bottom;
  });
  return {
    first: el.dataset.pathlandFirstItemIndex,
    paddingTop: el.style.paddingTop,
    paddingBottom: el.style.paddingBottom,
    scrollTop: sc ? sc.scrollTop : null,
    visiblePos: visible.slice(0, 4).map((k) => k.getAttribute('aria-posinset')),
    visibleText: visible.slice(0, 3).map((k) => (k.textContent || '').replace(/\s+/g, ' ').trim().slice(0, 34)),
  };
});
const setScroll = async (top) => {
  await page.evaluate((v) => {
    const el = document.querySelector('[data-pathland-lazy]');
    let sc = el.parentElement;
    while (sc && sc !== document.body) {
      const s = getComputedStyle(sc);
      if (/auto|scroll|overlay/.test(s.overflowY)) break;
      sc = sc.parentElement;
    }
    if (sc) sc.scrollTop = v;
  }, top);
  await page.waitForTimeout(900);
  console.log(top, JSON.stringify(await snap()));
};
await setScroll(0);
await setScroll(3000);
await setScroll(9000);
await setScroll(6000);
await setScroll(3000);
await setScroll(1000);
await setScroll(0);
await browser.close();
